describe('Navigation Menu Highlight', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's homepage
    });

    it('should highlight the active menu item', () => {
        cy.get('nav') // Adjust the selector to target your navigation bar
            .find('a.active') // Adjust the selector to target the active menu item
            .should('have.class', 'highlight'); // Adjust the class name as necessary
    });

    it('should not highlight inactive menu items', () => {
        cy.get('nav') // Adjust the selector to target your navigation bar
            .find('a') // Adjust the selector to target all menu items
            .each(($el) => {
                if (!$el.hasClass('active')) {
                    cy.wrap($el).should('not.have.class', 'highlight'); // Adjust the class name as necessary
                }
            });
    });
});
